with advanced as (
 update runtime_config_inventory_governance g set status='CLASSIFIED',domain_owner=d.domain_owner,authority_class=d.authority_class,scope=d.scope,risk=d.risk,mutability=d.target_mutability,consumer_contract=d.target_consumer_contract,admin_editable=d.admin_editable,requires_approval=d.requires_approval,classified_by='v41-c3r2f-issue-integration-consumer-closure',classified_at=now(),reason='V41-C3R2F active typed runtime consumer implemented',version=version+1
 from runtime_config_definitions d where g.configuration_key=d.definition_key and g.configuration_key in (
    'integration-sync.webhook-claim-lease-seconds',
    'integration-sync.webhook-max-attempts',
    'integration-sync.webhook-reconcile-delay-ms',
    'integration-sync.webhook-replay-window-seconds',
    'integration-sync.webhook-security.clock-skew-seconds',
    'integration-sync.webhook-security.default-max-body-bytes',
    'integration-sync.webhook-security.default-rate-limit-per-minute',
    'integration-sync.webhook-security.enabled',
    'integration-sync.webhook-security.nonce-cleanup-batch-size',
    'integration-sync.webhook-security.nonce-cleanup-interval-ms',
    'issue-projection.enabled',
    'issue-projection.max-attempts'
 ) and g.status='DISCOVERED' returning g.configuration_key,g.source_observation_hash
)
insert into runtime_config_inventory_governance_events(configuration_key,event_type,from_status,to_status,actor,reason,source_observation_hash,detail_json)
select configuration_key,'CLASSIFIED','DISCOVERED','CLASSIFIED','v41-c3r2f-issue-integration-consumer-closure','Active Issue Integration consumer classification confirmed',source_observation_hash,'{"stage":"V41_C3R2F_ISSUE_INTEGRATION_DOMAIN_CONSUMER_CLOSURE"}'::jsonb from advanced;

