do $$ declare v_ready integer; begin
  select count(*) into v_ready from runtime_config_definitions where definition_key in (
    'integration-sync.webhook-claim-lease-seconds',
    'integration-sync.webhook-max-attempts',
    'integration-sync.webhook-reconcile-delay-ms',
    'integration-sync.webhook-replay-window-seconds',
    'integration-sync.webhook-security.clock-skew-seconds',
    'integration-sync.webhook-security.default-max-body-bytes',
    'integration-sync.webhook-security.default-rate-limit-per-minute',
    'integration-sync.webhook-security.enabled',
    'integration-sync.webhook-security.nonce-cleanup-batch-size',
    'integration-sync.webhook-security.nonce-cleanup-interval-ms',
    'issue-projection.enabled',
    'issue-projection.max-attempts',
    'issue-projection.reconcile-batch-size',
    'issue-projection.reconcile-delay-ms',
    'issue-projection.retry-delay-seconds'
  ) and review_status='MIGRATION_READY' and migration_authorized=true and admin_editable=true;
  if v_ready<>15 then raise exception 'C3R2F_DOMAIN_DEFINITION_CLOSURE_INCOMPLETE expected=15 actual=%',v_ready; end if;
  if exists(select 1 from runtime_config_definitions where definition_key in ('integration-sync.circuit-failure-threshold','integration-sync.claim-limit','integration-sync.legacy-worker-enabled','integration-sync.max-attempts','integration-sync.projection-worker-enabled','integration-sync.projection-worker-interval-ms','integration-sync.provider-gateway','integration-sync.worker-enabled','integration-sync.worker-interval-ms','issue-projection-recovery.circuit-failure-threshold','issue-projection-recovery.claim-lease-seconds','issue-projection-recovery.claim-limit','issue-projection-recovery.index-delay-seconds','issue-projection-recovery.max-queue-depth','issue-projection.relay-provider','issue-relay.due-claim-limit','issue-relay.edge-max-attempts','issue-relay.retry-base-seconds') and (migration_authorized=true or admin_editable=true or review_status<>'RETIRED')) then raise exception 'C3R2F_RECLASSIFIED_AUTHORITY_LEAK'; end if;
  if (select count(*) from runtime_config_inventory_observations where configuration_key in ('integration-sync.webhook-claim-lease-seconds','integration-sync.webhook-max-attempts','integration-sync.webhook-reconcile-delay-ms','integration-sync.webhook-replay-window-seconds'))<>4 then raise exception 'C3R2F_CODE_ONLY_INVENTORY_MISSING'; end if;
  if exists(select 1 from runtime_config_inventory_governance where configuration_key in (
    'integration-sync.webhook-claim-lease-seconds',
    'integration-sync.webhook-max-attempts',
    'integration-sync.webhook-reconcile-delay-ms',
    'integration-sync.webhook-replay-window-seconds',
    'integration-sync.webhook-security.clock-skew-seconds',
    'integration-sync.webhook-security.default-max-body-bytes',
    'integration-sync.webhook-security.default-rate-limit-per-minute',
    'integration-sync.webhook-security.enabled',
    'integration-sync.webhook-security.nonce-cleanup-batch-size',
    'integration-sync.webhook-security.nonce-cleanup-interval-ms',
    'issue-projection.enabled',
    'issue-projection.max-attempts',
    'issue-projection.reconcile-batch-size',
    'issue-projection.reconcile-delay-ms',
    'issue-projection.retry-delay-seconds'
  ) and status in ('MIGRATED','LEGACY_RETIRED')) then raise exception 'C3R2F_PREMATURE_SINGLE_AUTHORITY_CUTOVER'; end if;
end $$;
